-- it 공식 계정(pinwith_it)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('it', 'it', $doc${"official":{"display_name":"PinWith Ufficiale","bio":"Liste create dal team di PinWith per farti scoprire posti da salvare e condividere."},"samples":[{"display_name":"Utente di esempio 1","bio":"Account di esempio creato da PinWith per mostrare come si organizza un viaggio insieme agli amici."},{"display_name":"Utente di esempio 2","bio":"Account di esempio creato da PinWith per mostrare come si organizza un viaggio insieme agli amici."},{"display_name":"Utente di esempio 3","bio":"Account di esempio creato da PinWith per mostrare come si organizza un viaggio insieme agli amici."}],"lists":[{"role":"plain","owner":"official","slug":"roma-classica-a-piedi","kind":"course","title":"Roma classica in un giorno","desc":"Il giro essenziale della Città Eterna: dalla Roma antica al Vaticano, per finire la sera a Trastevere. Si fa quasi tutto a piedi, con scarpe comode.","themes":["roma","primavolta","apiedi","storia","classici"],"sections":[{"name":"Mattina: Roma antica","by":"official","items":[{"place_id":"ChIJrRMgU7ZhLxMRxAOFkC7I8Sg","title":"Colosseo","memo":"Prenota online il biglietto combinato con Foro e Palatino ed entra al primo turno: meno coda e luce più morbida.","tags":["prenota","mattina"],"lat":41.89021,"lng":12.492231},{"place_id":"ChIJ782pg7NhLxMR5n3swAdAkfo","title":"Foro Romano","memo":"Incluso nello stesso biglietto del Colosseo. Porta acqua e cappello: c'è pochissima ombra.","tags":["archeologia","acqua"],"lat":41.892091,"lng":12.486438},{"place_id":"ChIJKzc56rhhLxMRdFBoVnQeLEk","title":"Pasqualino al Colosseo","memo":"Trattoria storica a due passi dall'Anfiteatro, comoda per un pranzo romano dopo la visita.","tags":["pranzo","trattoria"],"lat":41.889343,"lng":12.495223}]},{"name":"Pomeriggio: centro storico","by":"official","items":[{"place_id":"ChIJqUCGZ09gLxMRLM42IPpl0co","title":"Pantheon","memo":"Guarda in su verso l'oculo: nei giorni di pioggia l'acqua cade dentro e scorre via dai fori nel pavimento.","tags":["monumento","dafare"],"lat":41.898611,"lng":12.476873},{"place_id":"ChIJ1UCDJ1NgLxMRtrsCzOHxdvY","title":"Fontana di Trevi","memo":"Di giorno è sempre affollata: torna presto la mattina o tardi la sera per goderla con calma. Moneta di spalle, mano destra sopra la spalla sinistra.","tags":["tradizione","sera"],"lat":41.900933,"lng":12.483313},{"place_id":"ChIJ4T6-zEhgLxMRSa1VL3N0DyY","title":"Roscioli","memo":"Salumeria e cucina vicino a Campo de' Fiori, famosa per la carbonara. Meglio prenotare.","tags":["carbonara","prenota"],"lat":41.894256,"lng":12.474242}]},{"name":"Vaticano e sera a Trastevere","by":"official","items":[{"place_id":"ChIJKcGbg2NgLxMRthZkUqDs4M8","title":"Piazza San Pietro","memo":"Per la Basilica serve abbigliamento adeguato: spalle e ginocchia coperte. I Musei Vaticani vanno prenotati a parte.","tags":["vaticano","dresscode"],"lat":41.906488,"lng":12.453641},{"place_id":"ChIJ921caWhgLxMRM_bfeCcgn6M","title":"Trastevere","memo":"Perditi tra i vicoli dopo il tramonto: è il momento migliore per un aperitivo e una cena all'aperto.","tags":["serata","aperitivo"],"lat":41.884829,"lng":12.470402}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-dolomiti-seceda-braies-tre-cime","kind":"course","title":"[Vlog] Dolomiti: Seceda, Braies e Tre Cime","desc":"Tre giorni tra le cime più fotografate d'Italia: alba sul lago, creste in funivia e il giro delle Tre Cime. Qui trovi tutti i punti del vlog con orari consigliati per le foto e qualche trucco per evitare la folla.","themes":["dolomiti","vlog","trekking","fotografia","montagna"],"sections":[{"name":"Giorno 1: Val Gardena e Seceda","by":"official","items":[{"place_id":"ChIJk3dRF_ATeEcRturRh6kSf0c","title":"Funivia del Seceda","memo":"Si sale da Ortisei con la cabinovia e poi la funivia. Nel video al minuto 2:10 vedi la coda alle 10: prendi una delle prime corse.","tags":["funivia","ortisei"],"lat":46.598079,"lng":11.724296},{"place_id":"ChIJ-2KavI4TeEcRJb_XfBV82XE","title":"Cresta del Seceda","memo":"La classica inquadratura con le punte affilate delle Odle: cammina qualche minuto verso la croce e usa un grandangolo. Luce migliore la mattina presto.","tags":["drone","grandangolo"],"lat":46.600712,"lng":11.727093},{"place_id":"ChIJYdiwSSwTeEcRWMqOWuWVLD0","title":"Panorama Seceda","memo":"Punto un po' più tranquillo per i timelapse con le nuvole che passano sulle Odle. Porta un giacchino: anche d'estate c'è vento.","tags":["timelapse","vento"],"lat":46.600719,"lng":11.725799}]},{"name":"Giorno 2: Lago di Braies","by":"official","items":[{"place_id":"ChIJacfvIIoleEcRNN7cMwaXwrg","title":"Lago di Braies","memo":"Arriva all'alba: lago a specchio e quasi nessuno in giro. D'estate l'accesso in auto è regolato, controlla prima come funziona prenotazione e navette.","tags":["alba","riflessi"],"lat":46.693117,"lng":12.084608},{"place_id":"ChIJX6vceQAveEcRSNHq-4zG1qM","title":"Scalinata panoramica","memo":"Salendo qualche gradino hai il lago dall'alto con le barche di legno: è lo scatto di apertura del vlog. Perfetto con il cavalletto basso.","tags":["vistadallalto","cavalletto"],"lat":46.692773,"lng":12.086863}]},{"name":"Giorno 3: Tre Cime di Lavaredo","by":"official","items":[{"place_id":"ChIJ5cUQ8pzNeUcRsCGJCy2Mofc","title":"Partenza sentiero Tre Cime","memo":"Si arriva da Misurina con la strada a pedaggio fino al Rifugio Auronzo. Parti presto: il parcheggio si riempie in fretta in alta stagione.","tags":["pedaggio","presto"],"lat":46.612543,"lng":12.296555},{"place_id":"ChIJ07Cq8obPeUcRL9N6vtSn250","title":"Tre Cime di Lavaredo","memo":"Il giro ad anello richiede circa mezza giornata con soste. Dal lato nord, verso il Rifugio Locatelli, le tre pareti si vedono tutte insieme: lì luce più bella nel pomeriggio.","tags":["anello","pomeriggio"],"lat":46.618038,"lng":12.300959},{"place_id":"ChIJC5-ogovNeUcRWmx3_12Nvko","title":"Punto panoramico","memo":"Sosta perfetta per l'ultima ripresa del vlog al tramonto. Controlla il meteo: d'estate i temporali arrivano spesso nel pomeriggio.","tags":["tramonto","meteo"],"lat":46.6009,"lng":12.295422}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"sicilia-palermo-cefalu-tra-amici","kind":"collection","title":"Sicilia in tre: Palermo e Cefalù","desc":"Ognuno ha aggiunto i suoi posti del cuore per un weekend lungo tra Palermo, Monreale e Cefalù. Il programma finale lo trovi nei commenti del Duomo di Cefalù.","themes":["sicilia","palermo","cefalu","amici","weekend"],"sections":[{"name":"Le scelte di Utente 1: Palermo","by":"ex1","items":[{"place_id":"ChIJySXqmGHvGRMRancw-ZBf2ow","title":"Cattedrale di Palermo","memo":"Mix di stili arabo-normanno e barocco. Si può salire sui tetti per una bella vista sulla città.","tags":["arabonormanno","tetti"],"lat":38.114332,"lng":13.35605},{"place_id":"ChIJG10YKgDlGRMRgvss8tSK0oc","title":"Mercato di Ballarò","memo":"Il mercato storico più vivace: arancine, panelle e sfincione da mangiare in piedi. Meglio andarci la mattina.","tags":["streetfood","mattina"],"lat":38.110614,"lng":13.363675}]},{"name":"Le scelte di Utente 2: Monreale","by":"ex2","items":[{"place_id":"ChIJkzHupj_uGRMRguQLH5DlPgM","title":"Duomo di Monreale","memo":"I mosaici dorati sono incredibili, e anche il chiostro merita. Da Palermo si arriva in bus o in auto in poco tempo.","tags":["mosaici","gitafuoriporta"],"lat":38.082051,"lng":13.29207}]},{"name":"Le scelte di Utente 3: Cefalù","by":"ex3","items":[{"place_id":"ChIJa0OFxOk7FxMRLo4qlyTPcO8","title":"Duomo di Cefalù","memo":"La cattedrale normanna con la Rocca alle spalle. La piazza davanti è il posto giusto per una granita.","tags":["normanno","granita"],"lat":38.039875,"lng":14.023392},{"place_id":"ChIJMX1wtMA7FxMRNu8rpr1tQYM","title":"Mercatino estivo di Cefalù","memo":"Bancarelle nelle sere d'estate, carino per un giro dopo cena nel centro storico.","tags":["sera","estate"],"lat":38.033024,"lng":14.030494}]}],"comments":[{"place_id":"ChIJG10YKgDlGRMRgvss8tSK0oc","by":"ex1","body":"Ballarò lo facciamo il primo giorno a pranzo? Così mangiamo street food e risparmiamo per la cena.","replies":[{"by":"ex2","body":"Sì, ma andiamoci in tarda mattinata, il pomeriggio molte bancarelle chiudono."},{"by":"ex3","body":"Perfetto, io voglio provare le panelle. Portiamo contanti, non tutti accettano la carta."}]},{"place_id":"ChIJkzHupj_uGRMRguQLH5DlPgM","by":"ex2","body":"Monreale: noleggiamo l'auto o prendiamo il bus?","replies":[{"by":"ex1","body":"Per mezza giornata il bus va benissimo, in centro parcheggiare è un incubo."},{"by":"ex2","body":"Ok bus. Ricordatevi spalle coperte per entrare nel Duomo."}]},{"place_id":"ChIJySXqmGHvGRMRancw-ZBf2ow","by":"ex3","body":"I tetti della Cattedrale li facciamo al tramonto? Dicono che la vista sia top.","replies":[{"by":"ex1","body":"Controlliamo l'orario dell'ultimo ingresso il giorno prima, a volte chiude presto."}]},{"place_id":"ChIJMX1wtMA7FxMRNu8rpr1tQYM","by":"ex3","body":"A Cefalù dormiamo una notte o facciamo andata e ritorno in giornata da Palermo?","replies":[{"by":"ex2","body":"Col treno è circa un'ora, ma restare una notte ci fa godere il mercatino la sera e la spiaggia la mattina."},{"by":"ex1","body":"Dai, una notte a Cefalù. Se trovo un B&B economico prenoto io."}]},{"place_id":"ChIJa0OFxOk7FxMRLo4qlyTPcO8","by":"ex1","body":"Programma finale! Giorno 1: Ballarò a pranzo, Cattedrale di Palermo e tetti al tramonto. Giorno 2: mattina a Monreale in bus, pomeriggio treno per Cefalù e serata al mercatino. Giorno 3: Duomo di Cefalù presto, spiaggia e treno di rientro nel pomeriggio.","replies":[{"by":"ex2","body":"Approvato! Se piove il giorno 3 restiamo più a lungo nel centro di Cefalù."},{"by":"ex3","body":"Perfetto, compro i biglietti del treno stasera."}]}]},{"role":"food","owner":"official","slug":"napoli-pizza-tour","kind":"collection","title":"Napoli pizza tour","desc":"Dalla margherita classica alla pizza fritta, i nomi storici della pizza napoletana tra centro storico, Toledo e lungomare.","themes":["napoli","pizza","pizzafritta","streetfood","cibo"],"sections":[{"name":"Centro storico","by":"official","items":[{"place_id":"ChIJebC2jT8IOxMRQrZlcy2Xslo","title":"Da Michele","memo":"Menu cortissimo: margherita o marinara, ed è proprio questo il bello. Prendi il numero all'ingresso e preparati ad aspettare.","tags":["margherita","storica"],"lat":40.849756,"lng":14.2633},{"place_id":"ChIJuyXzSEIIOxMR5KQy1mftAr0","title":"Gino Sorbillo","memo":"In via dei Tribunali, impasto morbido e pizze enormi. La fila si forma già prima dell'apertura: arriva presto.","tags":["tribunali","fila"],"lat":40.850425,"lng":14.255358},{"place_id":"ChIJb95DkXcJOxMRS5W1zW6L5NU","title":"Antonio Sorbillo","memo":"Sempre in via dei Tribunali, un'alternativa quando la fila di fianco è troppo lunga.","tags":["tribunali","alternativa"],"lat":40.850486,"lng":14.255615},{"place_id":"ChIJabdK67sJOxMRw9vRlKTbJl8","title":"Zia Esterina a Spaccanapoli","memo":"Pizza fritta da passeggio vicino a Piazzetta Nilo: perfetta come spuntino mentre giri il centro storico.","tags":["pizzafritta","dapasseggio"],"lat":40.848736,"lng":14.256083}]},{"name":"Toledo e Piazza Trieste e Trento","by":"official","items":[{"place_id":"ChIJj1zFKlIIOxMRFcrlA-niFWM","title":"Sorbillo a portafoglio","memo":"La pizza piegata in quattro si mangia camminando: è il modo napoletano di fare pausa durante lo shopping su via Toledo.","tags":["portafoglio","veloce"],"lat":40.838193,"lng":14.248267},{"place_id":"ChIJVXnMzFMIOxMRXPPLqHBFes0","title":"Zia Esterina in Piazza Trieste e Trento","memo":"Comoda dopo una visita a Piazza del Plebiscito e alla Galleria Umberto I, a pochi passi.","tags":["pizzafritta","plebiscito"],"lat":40.837494,"lng":14.248296}]},{"name":"Lungomare","by":"official","items":[{"place_id":"ChIJ8TII-KoJOxMRT18Z450VDYs","title":"Sorbillo Lievito Madre al Mare","memo":"Pizza con vista sul Golfo e sul Castel dell'Ovo: ideale per una cena al tramonto dopo la passeggiata sul lungomare.","tags":["vistamare","tramonto"],"lat":40.831715,"lng":14.241729}]}],"comments":[]}]}$doc$::jsonb);
